/* Original generated Sengoku reconstruction artwork and photographed-style surface atlas.
 * These are creative visual reconstructions, not verified photographs of 1560 buildings.
 * Raster cells are packaged from the original generated atlases without runtime requests.
 */
(function (root) {
  "use strict";
  const SCENES = Object.freeze({"nanao":"data:image/jpeg;base64,","inabayama":"data:image/jpeg;base64,","odawara":"data:image/jpeg;base64,","kiyosu":"data:image/jpeg;base64,"});
  const SURFACES = Object.freeze({"wood":"data:image/jpeg;base64,","stone":"data:image/jpeg;base64,","earth":"data:image/jpeg;base64,","plaster":"data:image/jpeg;base64,","roof":"data:image/jpeg;base64,","ground":"data:image/jpeg;base64,"});

  const TYPES = Object.freeze({ mountain: "山城", hill: "平山城", plain: "平城", coast: "海辺の城" });
  const PALETTE = Object.freeze({ wood: "#76614a", stone: "#858375", earth: "#958064", plaster: "#e4ddc4", roof: "#545550", ground: "#748365" });
  const NAMED = Object.freeze({ nanao: "nanao", inabayama: "inabayama", odawara: "odawara", kiyosu: "kiyosu" });

  function scene(battle) {
    if (!battle || !["siege", "defense"].includes(battle.mode) && !battle.defending) return null;
    const castle = battle.targetCastle || {};
    const terrain = castle.terrain || battle.terrain || "plain";
    const profile = castle.profile || battle.profile || {};
    let key = NAMED[castle.id || battle.targetId];
    if (!key) {
      if (terrain === "mountain" || Number(profile.elevation) >= 180) key = castle.coastal || battle.coastal ? "nanao" : "inabayama";
      else if (terrain === "plain" && !castle.coastal && !battle.coastal) key = "kiyosu";
      else key = "odawara";
    }
    const name = castle.name || battle.targetName || battle.defender || "城郭";
    const type = TYPES[terrain] || (Number(profile.elevation) >= 180 ? TYPES.mountain : TYPES.hill);
    const named = Boolean(NAMED[castle.id || battle.targetId]);
    const caption = named
      ? `${name}の創作復元図。戦国期の土塁・木柵・曲輪・木造櫓を写実的に描いています。`
      : `${type}を題材にした創作復元図。地形別の城郭イメージで、各城の厳密な復原図ではありません。`;
    return { name, type, uri: SCENES[key], alt: `${name}・${type}の写実的な創作復元図`, caption, artwork: key, width: 768, height: 512 };
  }

  function createTextures(THREE, options = {}) {
    if (!THREE?.CanvasTexture || !root.document?.createElement || !root.Image) return null;
    const maps = {};
    const images = new Set();
    let disposed = false;
    const pending = [];
    for (const [name, uri] of Object.entries(SURFACES)) {
      const canvas = root.document.createElement("canvas");
      canvas.width = canvas.height = 512;
      const context = canvas.getContext("2d");
      if (!context) return null;
      context.fillStyle = PALETTE[name];
      context.fillRect(0, 0, 512, 512);
      const texture = new THREE.CanvasTexture(canvas);
      texture.colorSpace = THREE.SRGBColorSpace;
      texture.wrapS = texture.wrapT = THREE.RepeatWrapping;
      texture.anisotropy = Math.max(1, Math.min(8, Number(options.anisotropy) || 1));
      texture.repeat?.set(name === "ground" ? 3 : 2, name === "ground" ? 3 : 2);
      texture.name = `tenka-realistic-${name}`;
      maps[name] = texture;
      pending.push(new Promise((resolve) => {
        const image = new root.Image();
        let settled = false;
        const done = (loaded) => {
          if (settled) return;
          settled = true;
          images.delete(image);
          image.onload = image.onerror = null;
          if (loaded && !disposed) {
            context.drawImage(image, 0, 0, 512, 512);
            texture.needsUpdate = true;
            options.onLoad?.(name);
          }
          resolve(loaded && !disposed);
        };
        image.onload = () => done(true);
        image.onerror = () => done(false);
        images.add(image);
        image._tenkaCancel = () => done(false);
        image.src = uri;
      }));
    }
    maps.ready = Promise.all(pending);
    maps.dispose = () => {
      if (disposed) return;
      disposed = true;
      for (const image of images) image._tenkaCancel?.();
      images.clear();
      for (const name of Object.keys(SURFACES)) maps[name]?.dispose();
    };
    return maps;
  }

  root.TenkaCastles = Object.freeze({ scene, createTextures, version: 1 });
})(typeof window !== "undefined" ? window : globalThis);
